# /etc/nginx/nginx.conf (http context)
http {
    server_tokens off;                  # no version in headers or error pages
    client_max_body_size 2m;            # raise per location only where needed
    client_body_timeout 10s;            # slow-client protection
    client_header_timeout 10s;
    keepalive_timeout 15s;
    send_timeout 10s;

    ssl_protocols TLSv1.2 TLSv1.3;      # no SSLv3, TLS 1.0 or 1.1
    ssl_prefer_server_ciphers off;      # let modern clients choose
    ssl_session_tickets off;
    ssl_session_cache shared:SSL:10m;

    limit_req_zone $binary_remote_addr zone=login:10m rate=5r/m;

    # Catch-all server: answers requests for unknown host names
    server {
        listen 80 default_server;
        listen 443 ssl default_server;
        ssl_certificate     /etc/nginx/ssl/default.crt;
        ssl_certificate_key /etc/nginx/ssl/default.key;
        return 444;                     # close the connection without a response
    }

    include /etc/nginx/conf.d/*.conf;
}

# /etc/nginx/conf.d/example.com.conf
server {
    listen 80;
    server_name example.com www.example.com;
    return 301 https://example.com$request_uri;
}

server {
    listen 443 ssl;
    http2 on;
    server_name example.com;
    root /var/www/example.com/public;
    index index.html;

    ssl_certificate     /etc/nginx/ssl/example.com.fullchain.pem;
    ssl_certificate_key /etc/nginx/ssl/example.com.key;

    add_header Strict-Transport-Security "max-age=31536000" always;
    add_header X-Content-Type-Options "nosniff" always;
    add_header X-Frame-Options "SAMEORIGIN" always;

    autoindex off;

    location ~ /\.(?!well-known) { deny all; }
    location ~* \.(bak|sql|old|orig|swp|log)$ { deny all; }

    location / {
        limit_except GET HEAD POST { deny all; }
        try_files $uri $uri/ =404;
    }

    location = /login {
        limit_req zone=login burst=5 nodelay;
        try_files $uri =404;
    }
}

